from __future__ import annotations

import json
from pathlib import Path

ROOT = Path.home() / ".local/share/prediction-project-executor/campaigns/FULL-A2Z-LIVE-20261004-V4"
TASK_ID = "A2Z-V4-SOL-PROPOSAL-20261006-R1"
RESULT = ROOT / "model_results" / f"{TASK_ID}.json"

if not RESULT.is_file() or RESULT.is_symlink():
    raise SystemExit("SOL_MODEL_RESULT_MISSING")

result = json.loads(RESULT.read_text(encoding="utf-8"))
for key, wanted in {
    "schema": "PVA_GOVERNED_MODEL_COMPLETION_V1",
    "task_id": TASK_ID,
    "phase": "SOL_PROPOSAL",
    "model": "gpt-5.6-sol",
    "model_policy": "SOL_EXACT",
}.items():
    if result.get(key) != wanted:
        raise SystemExit(f"SOL_RESULT_{key.upper()}_MISMATCH")

final = result.get("final")
if not isinstance(final, str) or not final.strip():
    raise SystemExit("SOL_FINAL_MISSING")
try:
    proposal = json.loads(final)
except json.JSONDecodeError as exc:
    raise SystemExit(f"SOL_FINAL_NOT_JSON:{exc}")
if not isinstance(proposal, dict):
    raise SystemExit("SOL_PROPOSAL_NOT_OBJECT")

safety = proposal.get("safety")
diag = {
    "proposal_version": proposal.get("proposal_version"),
    "candidate_id": proposal.get("candidate_id"),
    "safety_present": "safety" in proposal,
    "safety_type": type(safety).__name__,
    "safety": safety,
    "top_level_live_trading": proposal.get("live_trading", "__MISSING__"),
    "top_level_paid_actions": proposal.get("paid_actions", "__MISSING__"),
    "top_level_wallet_actions": proposal.get("wallet_actions", "__MISSING__"),
}
if isinstance(safety, dict):
    for key in ("live_trading", "paid_actions", "wallet_actions"):
        value = safety.get(key, "__MISSING__")
        diag[key + "_value"] = value
        diag[key + "_type"] = type(value).__name__ if value != "__MISSING__" else "MISSING"

    if safety.get("live_trading") is not False:
        if "live_trading" not in safety:
            classification = "SAFETY_LIVE_TRADING_MISSING"
        elif isinstance(safety.get("live_trading"), str):
            classification = "SAFETY_LIVE_TRADING_STRING_OR_TEXT"
        else:
            classification = "SAFETY_LIVE_TRADING_NOT_EXACT_FALSE"
    elif safety.get("paid_actions") is not False:
        classification = "SAFETY_PAID_ACTIONS_NOT_EXACT_FALSE"
    elif safety.get("wallet_actions") is not False:
        classification = "SAFETY_WALLET_ACTIONS_NOT_EXACT_FALSE"
    else:
        classification = "SAFETY_EXACT_BOOLEAN_FALSE_TRIPLE"
else:
    classification = "SAFETY_NOT_OBJECT"

print("SOL_SAFETY_DIAG=" + json.dumps(diag, sort_keys=True, ensure_ascii=False))
print("SOL_SAFETY_CLASSIFICATION=" + classification)
print("NO_BUILD_OR_MEASUREMENT_STARTED=1")
print("NEXT_DECISION=SOL_REVISION_IF_INVALID_ELSE_REVERIFY")
